ALTER TABLE product
    ADD COLUMN category VARCHAR(40) NOT NULL DEFAULT 'TREATMENT';

ALTER TABLE product_ingredient
    ADD COLUMN is_active BOOLEAN NOT NULL DEFAULT FALSE;

CREATE TABLE product_concern (
    id UUID PRIMARY KEY,
    product_id UUID NOT NULL,
    concern_code VARCHAR(80) NOT NULL,
    relevance_weight INTEGER NOT NULL,
    CONSTRAINT fk_product_concern_product
        FOREIGN KEY (product_id) REFERENCES product (id),
    CONSTRAINT uk_product_concern_pair UNIQUE (product_id, concern_code),
    CONSTRAINT ck_product_concern_relevance_weight CHECK (relevance_weight BETWEEN 1 AND 5)
);

CREATE INDEX idx_product_concern_code ON product_concern (concern_code);




